CREATE TABLE IF NOT EXISTS public_observations (
  id TEXT PRIMARY KEY,
  observation_year INTEGER NOT NULL,
  geography_type TEXT NOT NULL,
  geography TEXT NOT NULL,
  domain TEXT NOT NULL,
  indicator TEXT NOT NULL,
  subgroup_label TEXT NOT NULL,
  numeric_value REAL NOT NULL,
  unit TEXT NOT NULL,
  pdf_page_number INTEGER NOT NULL,
  source_url TEXT NOT NULL,
  comparability TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS public_observations_filter_idx ON public_observations (observation_year, indicator, geography_type, subgroup_label);
